mapper.select:
SELECT SS.STAFFSCORE_ID,STA.REALNAME,SS.AUDITORS,SS.AUDITPROJECTNAME,SS.TOTALSCORE,SS.PROJECTID,ss.STATUS FROM TBL_NBSJ_STAFFSCORE ss LEFT JOIN TBL_STAFF sta ON SS.auditors = sta.STAFFID
and AUDITORS = #{re.auditors}
and AUDITPROJECTNAME like concat(concat('%',#{re.auditProjectName}),'%')
and unit = #{orgId}
ORDER BY staffScore_id
